    // 心跳线程池，用于定时发送心跳消息
    private static final ScheduledExecutorService HEARTBEATS = Executors.newSingleThreadScheduledExecutor(task -> {
        Thread thread = new Thread(task, "ai-agent-sse-heartbeat");
